import {session} from './auth.js';
import {scopedUrl,emitterContext} from './emitters.js';

export function createVerifactuViews({shell,heading,esc,icon,toast,modal,isAdmin,beforeAction,openInvoice,reload,onConfig=()=>{}}){
 const labels={pending:'Pendiente de envío',sending:'Enviando',accepted:'Aceptada en pruebas',accepted_errors:'Aceptada con errores',rejected:'Rechazada',network_error:'Conexión pendiente',blocked:'Requiere atención',verify_pending:'Verificando recepción',discarded:'Descartado'};
 const kinds={alta:'Alta',subsanacion:'Subsanación',anulacion:'Anulación de registro'};
 let timer;
 const real=record=>record.environment==='production';
 const badge=(status,record={})=>`<span class="badge ${['accepted'].includes(status)?'':status==='accepted_errors'?'partial':'draft'}">${esc(real(record)&&status==='accepted'?'Aceptada por la AEAT':real(record)&&status==='accepted_errors'?'Aceptada con errores por la AEAT':labels[status]||status)}</span>`;
 const where=record=>`<small class="cell-secondary vf-environment${real(record)?' vf-environment-real':''}">${real(record)?'AEAT real':'Pruebas'}</small>`;
 async function request(path,data){const response=await fetch('/api/verifactu/'+path,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:undefined);const value=await response.json();if(!response.ok)throw Error(value.error||'No se ha podido completar la operación de pruebas.');return value;}
 // A record already corrected or cancelled (and not rejected) is resolved: the server refuses a second correction.
 function followUp(record,records){const next=records.filter(r=>r.source_id===record.id&&r.status!=='rejected').sort((a,b)=>b.created_at.localeCompare(a.created_at))[0];if(!next)return null;const done=['accepted','accepted_errors'].includes(next.status),date=new Date(next.created_at).toLocaleDateString('es-ES');return next.kind==='anulacion'?(done?'Anulado el '+date:'Anulación en curso'):(done?'Subsanado el '+date:'Subsanación en curso');}
 function controls(record,records=[]){const resolved=followUp(record,records),detail=`<button class="btn ghost" data-vf-detail="${esc(record.id)}">Ver registro</button>${resolved?`<small class="cell-secondary vf-resolved">${esc(resolved)}</small>`:''}`;if(!emitterContext.active.active)return detail;return `${detail}${['pending','network_error','blocked','verify_pending'].includes(record.status)?`<button class="btn ghost" data-vf-action="retry" data-record="${esc(record.id)}">Reintentar</button>`:''}${!resolved&&record.canCorrect?`<button class="btn ghost" data-vf-correct="${esc(record.id)}">Subsanar registro</button>`:''}${!resolved&&record.canCancel?`<button class="btn ghost" data-vf-cancel="${esc(record.id)}">Anular registro</button>`:''}${!resolved&&record.canDiscard&&isAdmin()?`<button class="btn ghost" data-vf-discard="${esc(record.id)}">Descartar registro de prueba</button>`:''}`;}
 // What to do about an error, shown next to the AEAT message while the record is still unresolved.
 const hint=(record,records)=>['rejected','accepted_errors'].includes(record.status)&&record.kind!=='anulacion'&&record.hint&&!followUp(record,records)?`<small class="cell-secondary vf-hint"><strong>Qué hacer:</strong> ${esc(record.hint)}</small>`:'';
 function rows(records){return records.length?`<div class="tablewrap"><table class="vf-record-table"><thead><tr><th>Factura de prueba</th><th>Registro</th><th>Estado AEAT</th><th>Detalle</th><th>Acciones</th></tr></thead><tbody>${records.map(r=>`<tr><td><button class="rowlink" data-vf-invoice="${esc(r.invoice_id)}">${esc(r.number)}</button><small class="cell-secondary">${esc(r.client)}</small></td><td>${esc(kinds[r.kind]||r.kind)}<small class="cell-secondary">${esc(new Date(r.created_at).toLocaleString('es-ES'))}</small>${where(r)}</td><td>${badge(r.status,r)}</td><td>${esc(r.error||'—')}${r.code?`<small class="cell-secondary">Código ${esc(r.code)}</small>`:''}${hint(r,records)}${r.csv?`<small class="cell-secondary">CSV ${esc(r.csv)}</small>`:''}</td><td><div class="actions">${controls(r,records)}</div></td></tr>`).join('')}</tbody></table></div>`:`<div class="empty"><h3>Todavía no hay registros de prueba</h3><p>En Nueva factura marca «VERI*FACTU · Pruebas AEAT» y revisa el documento antes de emitirlo.</p></div>`;}
 function configuration(config){const cert=config.certificate||{},identity=config.identity;
  return `<section class="panel formpanel vf-configuration"><h2>Configuración del emisor seleccionado</h2><p>Certificado propio para la empresa o autónomo activo. Conexión exclusiva al entorno oficial de pruebas.</p><form id="vf-config-form"><div class="fields"><div class="field"><label for="vf-certificate">Certificado de este emisor (.p12 / .pfx)</label><input id="vf-certificate" type="file" accept=".p12,.pfx,application/x-pkcs12"><small>Máximo 100 KB. La clave privada se guarda cifrada en el servidor.</small></div><div class="field"><label for="vf-cert-password">Contraseña del archivo del certificado</label><input id="vf-cert-password" type="password" autocomplete="off"><small>Solo se usa para importar el archivo; no se conserva.</small></div></div>${cert.expires?`<div class="notice">Certificado de ${esc(cert.nif)} · válido hasta ${esc(new Date(cert.expires).toLocaleDateString('es-ES'))}.</div>`:'<p class="summary-note">Todavía no hay un certificado configurado para este emisor. Puedes emitir documentos de prueba que quedarán pendientes de envío.</p>'}<label class="check-label vf-auto"><input id="vf-auto-send" name="autoSend" type="checkbox" ${config.autoSend?'checked':''}>Enviar automáticamente a AEAT · solo pruebas</label><p class="summary-note">Si está desactivado, los documentos emitidos permanecen bloqueados y la cola queda en pausa. Una aceptación en pruebas no habilita el uso en producción.</p><div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">Guardar configuración de pruebas</button><button class="btn" type="button" data-vf-check>Comprobar conexión</button>${cert.expires?'<button class="btn ghost" type="button" data-vf-remove-cert>Quitar certificado</button>':''}</div></form><p class="summary-note">Instalación ${esc(identity.installation)} · versión ${esc(config.system?.version||'')} · ${config.dependencies?'Dependencias instaladas':'Pendiente de instalar dependencias en el servidor'}</p></section>`;
 }
 // The producer (whoever developed the program) is one for the whole installation: only the main account manages it.
 function producer(config){if(!session.user.isRoot)return '';const identity=config.identity,declaration=config.production?.declaration,system=config.system||{};
  return `<section class="panel formpanel vf-producer"><h2>Productor del programa</h2><p>Quien ha desarrollado el programa. Es común a todos los emisores y lo gestiona la cuenta principal.</p><form id="vf-producer-form"><div class="fields"><div class="field"><label for="vf-producer-name">Nombre del productor del programa</label><input id="vf-producer-name" name="producerName" value="${esc(identity.name)}" maxlength="120" required></div><div class="field"><label for="vf-producer-nif">NIF del productor</label><input id="vf-producer-nif" name="producerNif" value="${esc(identity.nif)}" maxlength="9" required></div></div><div class="form-error" role="alert"></div><div class="actions"><button class="btn primary" type="submit">Guardar datos del productor</button></div></form>
   <div class="vf-declaration"><h3>Declaración responsable del productor</h3><p class="summary-note">Una sola para todo el programa: la firma el productor y no se envía a la AEAT. Todos los usuarios pueden consultarla. Debe identificar el programa como se envía en cada registro: ${esc(system.name||'')} · identificador ${esc(system.id||'')} · versión ${esc(system.version||'')}.</p>${declaration?`<p class="vf-declaration-current"><a href="/api/verifactu/declaration" target="_blank" rel="noopener">${esc(declaration.name)}</a> · guardada el ${esc(new Date(declaration.at).toLocaleDateString('es-ES'))}</p>`:'<p class="summary-note">Todavía no se ha guardado. Sin ella no se puede activar VERI*FACTU real.</p>'}<div class="field"><label for="vf-declaration-file">${declaration?'Sustituir':'Guardar'} la declaración (PDF)</label><input id="vf-declaration-file" type="file" accept="application/pdf"><button class="btn" type="button" data-vf-declaration-save>Guardar declaración</button></div></div></section>`;
 }
 async function refreshRows(){const element=document.querySelector('#vf-record-rows');if(!element)return;try{const data=await request('records');if(element.isConnected)element.innerHTML=rows(data.records);}catch(error){toast(error.message);}timer=setTimeout(refreshRows,5000);}
 async function render(){clearTimeout(timer);try{const [config,data]=await Promise.all([request('config'),request('records')]);onConfig(config);shell(heading('VERI*FACTU · pruebas','Conexión experimental propia con la AEAT para el emisor seleccionado.')+`${config.production?.active?`<div class="notice warning vf-real-banner"><strong>VERI*FACTU real activo desde el ${esc(new Date(config.production.since).toLocaleDateString('es-ES'))}</strong><p>Las facturas de este emisor se envían a la AEAT real y figuran aquí como «AEAT real». Las facturas de pruebas usan la serie PRUEBAS- y no tocan la numeración real.</p></div>`:''}<div class="notice vf-warning"><strong>Entorno oficial de pruebas</strong><p>Los documentos de este apartado están separados de la facturación habitual y no tienen validez fiscal.</p><p>Emisiones inmodificables · ${config.autoSend?'envío automático activado':'envíos en pausa'}.</p></div><section class="panel" id="vf-record-rows">${rows(data.records)}</section>${producer(config)}${isAdmin()?configuration(config):'<p class="summary-note">Un administrador configura el certificado y los envíos de este emisor. Solo se muestran tus registros.</p>'}`,'VERI*FACTU · pruebas');timer=setTimeout(refreshRows,5000);}catch(error){toast(error.message);}}
 async function loadPanel(invoice){clearTimeout(timer);const element=document.querySelector('#vf-invoice-status');if(!element)return;try{const config=await request('config'),data=await request('records');const related=data.records.filter(r=>r.invoice_id===invoice.id);if(!element.isConnected)return;const live=related.some(real);element.innerHTML=`<strong>${live?'VERI*FACTU · AEAT':'VERI*FACTU · Pruebas AEAT'}</strong><p>Documento bloqueado desde su emisión.</p>${!live&&!config.autoSend?'<p>Envíos en pausa. Configura el certificado y el envío automático para comunicarlo.</p>':''}${related.map(record=>`<div class="vf-panel-record">${badge(record.status,record)}<small>${esc(kinds[record.kind])}</small>${record.error?`<p>${esc(record.error)}</p>`:''}${hint(record,data.records)}<div class="actions">${controls(record,data.records)}</div></div>`).join('')}`;timer=setTimeout(()=>loadPanel(invoice),5000);}catch(error){if(element.isConnected)element.textContent=error.message;}}
 function dialog(content){modal.className='finance-modal';modal.innerHTML=`<button class="iconbtn close" data-action="close-modal" aria-label="Cerrar">${icon('close')}</button>${content}`;if(!modal.open)modal.showModal();}
 document.addEventListener('click',async event=>{const button=event.target.closest('button');if(!button)return;try{
  if(button.dataset.vfInvoice){await beforeAction();openInvoice(button.dataset.vfInvoice);return;}
  if(button.dataset.vfDetail){const value=await request('records/'+encodeURIComponent(button.dataset.vfDetail));const r=value.record;dialog(`<h2>Registro de pruebas AEAT</h2><p>${badge(r.status)} · ${esc(kinds[r.kind])}</p><p class="vf-hash">Huella ${esc(r.hash)}</p><p>${esc(r.error||'Sin incidencias comunicadas.')}${r.csv?'<br>CSV '+esc(r.csv):''}</p><a class="btn" href="${scopedUrl('/api/verifactu/records/'+encodeURIComponent(r.id)+'/xml')}" download>Descargar XML enviado</a><h3>Intentos de comunicación</h3>${value.attempts.map(a=>`<p>${esc(new Date(a.created_at).toLocaleString('es-ES'))} · ${esc(labels[a.status]||a.status)}<br>${esc(a.error)}</p>`).join('')||'<p>Todavía no hay intentos de envío.</p>'}`);return;}
  if(button.dataset.vfAction){button.disabled=true;await beforeAction();await request('action',{recordId:button.dataset.record,action:button.dataset.vfAction});toast('Registro pendiente de reintento. El envío automático debe estar activado.');return;}
  if(button.dataset.vfCorrect||button.dataset.vfCancel){const cancel=!!button.dataset.vfCancel,recordId=button.dataset.vfCancel||button.dataset.vfCorrect;
   const {record,diagnosis}=await request('records/'+encodeURIComponent(recordId)),sent=diagnosis.sent||{},marked=name=>diagnosis.field===(name==='description'?'description':'recipient')?' vf-field-error':'';
   const answer=record.error?`<div class="notice warning vf-diagnosis"><p><strong>La AEAT respondió${record.code?` (código ${esc(record.code)})`:''}:</strong> ${esc(record.error)}</p><p><strong>Qué hacer:</strong> ${esc(diagnosis.hint)}</p></div>`:'';
   const test=!real(record),noun=test?' de prueba':'';
   dialog(`<h2>${cancel?'Anular registro'+noun:'Subsanar registro'+noun}</h2><p>${cancel?'Se añadirá un registro de anulación, conservando la factura y su alta.':'Se enviará un registro nuevo con estos datos corregidos. La factura emitida no cambia y el registro original se conserva.'}</p>${!test?`<div class="notice warning"><strong>AEAT real.</strong> ${cancel?'Se comunicará a la AEAT la anulación del registro de esta factura. Úsalo solo si la factura se expidió por error.':'La subsanación se comunicará a la AEAT.'}</div>`:''}${answer}<form id="vf-action-form" data-record="${esc(recordId)}" data-kind="${cancel?'anular':'subsanar'}"><div class="fields">${cancel?'<div class="field full"><label for="vf-reason">Motivo de anulación</label><textarea id="vf-reason" name="reason" required minlength="3" maxlength="500"></textarea></div>':`<div class="field${marked('recipient')}"><label for="vf-recipient-name">Nombre del destinatario en el registro</label><input id="vf-recipient-name" name="recipientName" maxlength="120" value="${esc(sent.recipientName||'')}"></div><div class="field${marked('recipient')}"><label for="vf-recipient-nif">NIF del destinatario en el registro</label><input id="vf-recipient-nif" name="recipientNif" maxlength="9" value="${esc(sent.recipientNif||'')}"></div><div class="field full${marked('description')}"><label for="vf-description">Descripción del registro</label><textarea id="vf-description" name="description" maxlength="500">${esc(sent.description||'')}</textarea><small>Son los datos que se enviaron. Corrige los marcados; el resto se envía como está.</small></div><div class="field full"><label class="check-label"><input type="checkbox" name="updateClient" checked> Actualizar también la ficha del cliente</label><small>Las próximas facturas usarán este nombre y NIF. La factura ya emitida no cambia.</small></div>`}</div><div class="form-error" role="alert"></div><button class="btn primary" type="submit">${test?`Crear ${cancel?'anulación':'subsanación'} de prueba`:`Enviar ${cancel?'anulación':'subsanación'} a la AEAT`}</button></form>`);
   modal.querySelector('.vf-field-error input,.vf-field-error textarea,#vf-reason')?.focus();return;}
  if(button.dataset.vfDiscard){const {diagnosis}=await request('records/'+encodeURIComponent(button.dataset.vfDiscard));dialog(`<h2>Descartar registro de prueba</h2><div class="notice warning vf-diagnosis"><p>${esc(diagnosis.hint)}</p></div><p>El registro y la respuesta de la AEAT se conservan; solo deja de figurar como pendiente de corregir. No se envía nada a la AEAT.</p><div class="actions"><button type="button" class="btn ghost" data-action="close-modal">Cancelar</button><button type="button" class="btn primary" data-vf-discard-confirm="${esc(button.dataset.vfDiscard)}">Descartar registro</button></div>`);return;}
  if(button.dataset.vfDiscardConfirm){button.disabled=true;await beforeAction();await request('action',{recordId:button.dataset.vfDiscardConfirm,action:'discard'});modal.close();toast('Registro de prueba descartado. Se conserva con la respuesta de la AEAT.');await refreshRows();return;}
  if(button.hasAttribute('data-vf-check')){button.disabled=true;await beforeAction();await request('check',{});toast('Conexión confirmada con el entorno oficial de pruebas.');return;}
  if(button.hasAttribute('data-vf-remove-cert')){button.disabled=true;await beforeAction();await request('config',{removeCertificate:true,autoSend:false});await render();toast('Certificado retirado; envíos en pausa.');}
 }catch(error){toast(error.message);}finally{if(button.isConnected&&(button.hasAttribute('data-vf-check')||button.dataset.vfAction||button.hasAttribute('data-vf-remove-cert')))button.disabled=false;}});
 document.addEventListener('submit',async event=>{const form=event.target;if(!['vf-config-form','vf-action-form','vf-producer-form'].includes(form.id))return;event.preventDefault();const button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';try{await beforeAction();
  if(form.id==='vf-producer-form'){await request('config',Object.fromEntries(new FormData(form)));await render();toast('Datos del productor guardados.');return;}
  if(form.id==='vf-config-form'){const fields=Object.fromEntries(new FormData(form)),file=form.querySelector('#vf-certificate').files[0];const payload={...fields,autoSend:form.querySelector('#vf-auto-send').checked};if(file){if(file.size>100000)throw Error('El certificado supera 100 KB.');payload.certificate=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('No se puede leer el certificado.'));reader.readAsDataURL(file);});payload.password=form.querySelector('#vf-cert-password').value;}await request('config',payload);form.querySelector('#vf-cert-password').value='';await render();toast('Configuración de pruebas guardada.');}
  else{const details=Object.fromEntries(new FormData(form)),updateClient=details.updateClient==='on';delete details.updateClient;const result=await request('action',{recordId:form.dataset.record,action:form.dataset.kind,details,updateClient});if(result.clientUpdated)await reload();modal.close();toast('Nuevo registro VERI*FACTU creado'+(result.clientUpdated?' y ficha del cliente actualizada.':'. El original permanece conservado.'));await refreshRows();}
 }catch(exc){error.textContent=exc.message;button.disabled=false;}});

 const check=(ok,text)=>`<li class="${ok?'vf-ok':'vf-missing'}">${icon(ok?'check':'close')} ${text}</li>`;
 function productionSlot(){return isAdmin()?`<section class="panel formpanel vf-production" id="vf-production"><div class="sectionhead"><h2>VERI*FACTU real</h2>${icon('shield')}</div><p class="summary-note">Cargando…</p></section>`:'';}
 async function loadProduction(){const slot=document.querySelector('#vf-production');if(!slot)return;
  let config;try{config=await request('config');onConfig(config);}catch(error){slot.querySelector('.summary-note').textContent=error.message;return;}
  if(!slot.isConnected)return;
  // An older server process does not know this mode yet: say so instead of waiting forever.
  if(!config.production||!config.system){slot.querySelector('.summary-note').textContent='El servidor en marcha es anterior a esta función. Reinícialo (Ctrl+C y npm start) y recarga la página.';return;}
  const p=config.production,cert=config.certificate||{},identity=config.identity,system=config.system,expired=!cert.expires||new Date(cert.expires)<=new Date();
  const ready=!!(identity.name&&identity.nif&&p.declaration&&cert.expires&&!expired);
  slot.innerHTML=`<div class="sectionhead"><h2>VERI*FACTU real</h2>${icon('shield')}</div>${p.active?`<div class="notice warning"><strong>Activo desde el ${esc(new Date(p.since).toLocaleString('es-ES'))}.</strong> Todas las facturas que emite este emisor se envían a la AEAT real, salvo las de ejemplo y las de pruebas (serie PRUEBAS-). No se pueden anular, eliminar ni renumerar desde la aplicación.</div>`:`<p class="summary-note">Envía las facturas de este emisor al servicio real de la AEAT. Se activa por emisor: desde ese momento se remiten todas sus facturas. El modo de pruebas sigue disponible con la serie PRUEBAS-.</p>`}
   <ul class="vf-requirements">${check(identity.name&&identity.nif,`Productor del programa: ${identity.name?esc(identity.name+' · '+identity.nif):'sin configurar (cuenta principal, en VERI*FACTU · pruebas)'}`)}${check(!!p.declaration,p.declaration?`Declaración responsable del productor del programa: <a href="/api/verifactu/declaration" target="_blank" rel="noopener">${esc(p.declaration.name)}</a> (la gestiona la cuenta principal)`:'Declaración responsable del productor del programa: sin guardar (la cuenta principal, en VERI*FACTU · pruebas → Productor del programa)')}${check(cert.expires&&!expired,cert.expires?`Certificado del emisor ${expired?'caducado':'válido hasta el '+esc(new Date(cert.expires).toLocaleDateString('es-ES'))}`:'Certificado del emisor: sin configurar (en VERI*FACTU · pruebas)')}</ul>
   <div class="vf-identification"><strong>Identificación enviada en cada registro</strong><p>Debe coincidir con la declaración responsable: ${esc(system.name)} · identificador ${esc(system.id)} · versión ${esc(system.version)} · instalación ${esc(identity.installation||'')}.</p></div>
   ${p.active?(p.canDeactivate?'<div class="actions"><button class="btn ghost" type="button" data-vf-production-off>Desactivar VERI*FACTU real</button><small>Solo mientras no se haya remitido ninguna factura este año.</small></div>':'<p class="summary-note">Ya se han remitido facturas este año: la modalidad VERI*FACTU se mantiene durante el resto del año natural.</p>'):`<form id="vf-production-form"><label class="check-label"><input type="checkbox" name="confirmDeclaration" required> La declaración responsable del productor está firmada y corresponde a este programa y versión.</label><label class="check-label"><input type="checkbox" name="confirmAllInvoices" required> Entiendo que, desde la activación, todas las facturas de este emisor se remitirán a la AEAT real y que la modalidad se mantiene el resto del año natural.</label><div class="form-error" role="alert"></div><button class="btn primary" type="submit" ${ready?'':'disabled'}>Activar VERI*FACTU real</button>${ready?'':'<small>Completa los requisitos marcados con ✕.</small>'}</form>`}`;}
 document.addEventListener('click',async event=>{const target=event.target.closest('[data-vf-declaration-save],[data-vf-production-off]');if(!target)return;
  try{target.disabled=true;await beforeAction();
   if(target.hasAttribute('data-vf-declaration-save')){const file=document.querySelector('#vf-declaration-file')?.files[0];if(!file)throw Error('Selecciona el PDF de la declaración responsable.');if(file.size>10_000_000)throw Error('La declaración supera 10 MB.');
    const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(Error('No se puede leer el archivo.'));reader.readAsDataURL(file);});
    await request('declaration',{file:data,name:file.name});await render();toast('Declaración responsable guardada.');return;}
   if(!confirm('¿Desactivar VERI*FACTU real en este emisor? Sus próximas facturas dejarán de enviarse a la AEAT.'))return;
   await request('production',{active:false});await loadProduction();toast('VERI*FACTU real desactivado.');
  }catch(error){toast(error.message);}finally{if(target.isConnected)target.disabled=false;}});
 document.addEventListener('submit',async event=>{if(event.target.id!=='vf-production-form')return;event.preventDefault();const form=event.target,button=form.querySelector('[type=submit]'),error=form.querySelector('.form-error');button.disabled=true;error.textContent='';
  try{await beforeAction();await request('production',{active:true,confirmDeclaration:form.confirmDeclaration.checked,confirmAllInvoices:form.confirmAllInvoices.checked});await loadProduction();toast('VERI*FACTU real activado. Las próximas facturas se enviarán a la AEAT.');}
  catch(exc){error.textContent=exc.message;button.disabled=false;}});
 return {render,loadPanel,productionSlot,loadProduction};
}
